// components/admin-header.tsx
"use client";

import React, { useEffect, useState } from "react";
import Link from "next/link";
import { createClient } from "@/lib/supabase/client";
import { useRouter } from "next/navigation";
import type { User } from "@supabase/supabase-js";

export function AdminHeader() {
  const [email, setEmail] = useState<string | null>(null);
  const router = useRouter();

  useEffect(() => {
    const supabase = createClient();
    if (!supabase) return;

    // tipamos la respuesta para evitar 'any' implícito
    supabase
      .auth
      .getUser()
      .then((res: { data: { user: User | null } | null; error?: unknown }) => {
        const user = res?.data?.user ?? null;
        setEmail(user?.email ?? null);
      })
      .catch((err: unknown) => {
        console.warn("[AdminHeader] getUser failed:", err);
        setEmail(null);
      });
  }, []);

  const handleLogout = async () => {
    try {
      const supabase = createClient();
      if (supabase) {
        // supabase.auth.signOut() devuelve { error }
        const signOutRes = await supabase.auth.signOut();
        if ((signOutRes as any)?.error) {
          console.warn("[AdminHeader] client signOut returned error:", (signOutRes as any).error);
        }
      }

      // Limpiar sesión en server (cookies HTTP-only)
      try {
        await fetch("/api/auth/clear-session", {
          method: "POST",
          credentials: "same-origin",
        });
      } catch (e: unknown) {
        console.warn("[AdminHeader] clear-session fetch failed:", e);
      }

      setEmail(null);
      router.push("/");
    } catch (err: unknown) {
      console.error("[AdminHeader] logout error:", err);
      router.push("/");
    }
  };

  return (
    <header className="border-b border-border sticky top-0 z-50 bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
      <div className="container mx-auto px-4 py-4 flex items-center justify-between">
        <Link href="/" className="text-2xl font-bold text-primary">
          Casa Ensueño • Store
        </Link>
        <nav className="flex items-center gap-4">
          <Link href="/admin/registrations" className="text-sm font-medium hover:text-primary transition-colors">
            Solicitudes
          </Link>
          {email ? (
            <>
              <span className="text-sm text-muted-foreground">{email}</span>
              <button onClick={handleLogout} className="text-sm font-medium hover:text-primary transition-colors">
                Salir
              </button>
            </>
          ) : (
            <Link href="/auth/login" className="text-sm font-medium hover:text-primary transition-colors">
              Iniciar sesión
            </Link>
          )}
        </nav>
      </div>
    </header>
  );
}
